var worker = new Thread(() =>
{
    try { WriteBigFile(); }
    finally { Flush(); }        // у фонового может не выполниться
})
{
    IsBackground = true
};
worker.Start();

// без Join: Main закончился → процесс завершается, worker обрывается
worker.Join();                  // Main стоит, пока worker не закончит; finally выполнится

